static int RidersAfter(int on, int off)
{
    var bus = new Bus("12A");
    bus.GetOn(on);
    for (int i = 0; i < off; i++) bus.GetOff();
    return bus.Riders;
}
static int TwoStops(int first, int second)
{
    var bus = new Bus("12A");
    bus.GetOn(first);
    bus.GetOn(second);
    return bus.Riders;
}
